// Port of library/proc_macro/src/bridge/server.rs
//
//! Server-side traits.
//
// PORT: the `Server` trait (generated by `with_api!(define_server, ..)`) is an interface generic over the
// associated types `TokenStream`, `Span`, `Symbol`. Its associated fns without `self` (`intern_symbol`,
// `with_symbol_string`) and the `TokenStream: Default` bound are `ServerStatics`: the statics of the server's
// class, reached as `server.constructor` (rustc_expand's `Rustc` declares them as `static`). `HandleStore<S>`
// carries them in its field `S`, which stands for the type parameter.
//
// PORT: `Marked<S::X, client::X>` is `S::X` (see mod.ts). The handle-store codecs below are the impls for the
// marked types; `Dispatcher.dispatch` (`define_dispatcher!`) names the codec of each argument and return type.
//
// PORT: the cross-thread execution strategy (`MessagePipe`, `thread::spawn`) needs a second thread with its own
// thread-locals for the client; it stops with `unported(..)`. It runs for `-Zproc-macro-execution-strategy=
// cross-thread` and for proc macros nested inside a same-thread one (`TokenStream::expand_expr`).

import { assert, panicking, unported } from "../../std/panic.ts";
import type { MutRef } from "../../std/mut_ref.ts";
import type { Result } from "../../std/result.ts";
import { Buffer } from "./buffer.ts";
import { Client } from "./client.ts";
import { Closure } from "./closure.ts";
import { type Handle, InternedStore, OwnedStore } from "./handle.ts";
import {
  type BridgeConfig,
  decode_ApiTags,
  decode_Bound,
  decode_Diagnostic,
  decode_Option,
  decode_Result,
  decode_TokenTree,
  type Diagnostic,
  encode_ExpnGlobals,
  encode_Literal,
  encode_Option,
  encode_Range,
  encode_Result,
  encode_TokenTree,
  type ExpnGlobals,
  type Literal,
  Mark_Marked,
  type TokenTree,
} from "./mod.ts";
import { catch_unwind, decode_PanicMessage, encode_PanicMessage, PanicMessage } from "./panic_message.ts";
import {
  type Decode,
  decode_NonZero_u32,
  decode_str,
  decode_usize,
  decode_Vec,
  type Encode,
  encode_bool,
  encode_NonZero_u32,
  encode_String,
  encode_tuple2,
  encode_unit,
  encode_usize,
  encode_Vec,
} from "./rpc.ts";
import { decode_MarkedSymbol, encode_MarkedSymbol } from "./symbol.ts";

/** PORT: `std::ops::Range<usize>`. */
export interface Range {
  start: number;
  end: number;
}

/** PORT: `std::ops::Bound<usize>`. */
export type Bound = { readonly $: "Included"; _0: number } | { readonly $: "Excluded"; _0: number } | { readonly $: "Unbounded" };

// std-type: library/proc_macro/src/bridge/server.rs:15 HandleStore
export class HandleStore<TokenStream, Span, Symbol> {
  constructor(
    public token_stream: OwnedStore<TokenStream>,
    public span: InternedStore<Span>,
    /** PORT: the type parameter `S: Server`'s associated fns (see the header). */
    public S: ServerStatics<TokenStream, Symbol>,
  ) {}

  // std: library/proc_macro/src/bridge/server.rs:21 new
  static new<TokenStream, Span, Symbol>(S: ServerStatics<TokenStream, Symbol>): HandleStore<TokenStream, Span, Symbol> {
    return new HandleStore<TokenStream, Span, Symbol>(OwnedStore.new(TOKEN_STREAM), InternedStore.new(SPAN), S);
  }
}

// `static TOKEN_STREAM: AtomicU32 = AtomicU32::new(1);` / `static SPAN: AtomicU32 = AtomicU32::new(1);` (in
// `HandleStore::new`: one pair of counters for the whole process, shared by every server type).
const TOKEN_STREAM: MutRef<number> = { value: 1 };
const SPAN: MutRef<number> = { value: 1 };

// impl<S: Server> Encode<HandleStore<S>> for MarkedTokenStream<S>
// std: library/proc_macro/src/bridge/server.rs:37 encode
export function encode_MarkedTokenStream<TS, Sp, Sy>(self: TS, w: Buffer, s: HandleStore<TS, Sp, Sy>): void {
  encode_NonZero_u32(s.token_stream.alloc(self), w, s);
}

// impl<S: Server> Decode<'_, '_, HandleStore<S>> for MarkedTokenStream<S>
// std: library/proc_macro/src/bridge/server.rs:43 decode
export function decode_MarkedTokenStream<TS, Sp, Sy>(r: MutRef<Uint8Array>, s: HandleStore<TS, Sp, Sy>): TS {
  return s.token_stream.take(decode_Handle(r));
}

// impl<'s, S: Server> Decode<'_, 's, HandleStore<S>> for &'s MarkedTokenStream<S>
// std: library/proc_macro/src/bridge/server.rs:49 decode
export function decode_ref_MarkedTokenStream<TS, Sp, Sy>(r: MutRef<Uint8Array>, s: HandleStore<TS, Sp, Sy>): TS {
  return s.token_stream.index(decode_Handle(r));
}

// impl<S: Server> Encode<HandleStore<S>> for MarkedSpan<S>
// std: library/proc_macro/src/bridge/server.rs:55 encode
export function encode_MarkedSpan<TS, Sp, Sy>(self: Sp, w: Buffer, s: HandleStore<TS, Sp, Sy>): void {
  encode_NonZero_u32(s.span.alloc(self), w, s);
}

// impl<S: Server> Decode<'_, '_, HandleStore<S>> for MarkedSpan<S>
// std: library/proc_macro/src/bridge/server.rs:61 decode
export function decode_MarkedSpan<TS, Sp, Sy>(r: MutRef<Uint8Array>, s: HandleStore<TS, Sp, Sy>): Sp {
  return s.span.copy(decode_Handle(r));
}

/** `handle::Handle::decode(r, &mut ())` */
function decode_Handle(r: MutRef<Uint8Array>): Handle {
  return decode_NonZero_u32(r, undefined);
}

// with_api!(define_server, Self::TokenStream, Self::Span, Self::Symbol);
// std-type: library/proc_macro/src/bridge/server.rs:70 Server
// PORT: methods in `with_api!` order (bridge/mod.rs:36-79), after `globals`.
export interface Server<TokenStream, Span, Symbol> {
  // std: library/proc_macro/src/bridge/server.rs:75 globals
  globals(): ExpnGlobals<Span>;

  track_env_var(var_: string, value: string | undefined): void;
  track_path(path: string): void;
  literal_from_str(s: string): Result<Literal<Span, Symbol>, string>;
  emit_diagnostic(diagnostic: Diagnostic<Span>): void;

  ts_drop(stream: TokenStream): void;
  ts_clone(stream: TokenStream): TokenStream;
  ts_is_empty(stream: TokenStream): boolean;
  ts_expand_expr(stream: TokenStream): Result<TokenStream, undefined>;
  ts_from_str(src: string): Result<TokenStream, string>;
  ts_to_string(stream: TokenStream): string;
  ts_from_token_tree(tree: TokenTree<TokenStream, Span, Symbol>): TokenStream;
  ts_concat_trees(base: TokenStream | undefined, trees: TokenTree<TokenStream, Span, Symbol>[]): TokenStream;
  ts_concat_streams(base: TokenStream | undefined, streams: TokenStream[]): TokenStream;
  ts_into_trees(stream: TokenStream): TokenTree<TokenStream, Span, Symbol>[];

  span_debug(span: Span): string;
  span_parent(span: Span): Span | undefined;
  span_source(span: Span): Span;
  span_byte_range(span: Span): Range;
  span_start(span: Span): Span;
  span_end(span: Span): Span;
  span_line(span: Span): number;
  span_column(span: Span): number;
  span_file(span: Span): string;
  span_local_file(span: Span): string | undefined;
  span_join(span: Span, other: Span): Span | undefined;
  span_subspan(span: Span, start: Bound, end: Bound): Span | undefined;
  span_resolved_at(span: Span, at: Span): Span;
  span_source_text(span: Span): string | undefined;
  span_save_span(span: Span): number;
  span_recover_proc_macro_span(id: number): Span;

  symbol_normalize_and_validate_ident(string: string): Result<Symbol, undefined>;
}

/** The associated fns of `Server` that take no `self`, and the `TokenStream: Default` bound. */
export interface ServerStatics<TokenStream, Symbol> {
  /// Intern a symbol received from RPC
  // std: library/proc_macro/src/bridge/server.rs:78 intern_symbol
  intern_symbol(ident: string): Symbol;

  /// Recover the string value of a symbol, and invoke a callback with it.
  // std: library/proc_macro/src/bridge/server.rs:81 with_symbol_string
  with_symbol_string(symbol: Symbol, f: (s: string) => void): void;

  /**
   * `<S::TokenStream as Default>::default()`.
   * PORT: optional so that a server class without it still type-checks; `run1` / `run2` stop with `unported` when
   * they need it and it is missing.
   */
  default_TokenStream?(): TokenStream;
}

/** PORT: `S` (the server's type) for its associated fns: the server's class. */
function statics_of<TokenStream, Span, Symbol>(server: Server<TokenStream, Span, Symbol>): ServerStatics<TokenStream, Symbol> {
  return (server as unknown as { constructor: ServerStatics<TokenStream, Symbol> }).constructor;
}

// FIXME(eddyb) `pub` only for `ExecutionStrategy` below.
// std-type: library/proc_macro/src/bridge/server.rs:90 Dispatcher
export class Dispatcher<TokenStream, Span, Symbol> {
  constructor(
    public handle_store: HandleStore<TokenStream, Span, Symbol>,
    public server: Server<TokenStream, Span, Symbol>,
  ) {}

  // with_api!(define_dispatcher, MarkedTokenStream<S>, MarkedSpan<S>, MarkedSymbol<S>);
  // std: library/proc_macro/src/bridge/server.rs:100 dispatch
  dispatch(buf: Buffer): Buffer {
    const { handle_store, server } = this;
    type TS = TokenStream;
    type HS = HandleStore<TokenStream, Span, Symbol>;
    const { unmark, mark } = Mark_Marked;
    // The codecs of the marked types (`MarkedTokenStream<S>`, `&MarkedTokenStream<S>`, `MarkedSpan<S>`,
    // `MarkedSymbol<S>`) and of the compound types built from them.
    const enc_ts: Encode<TS, HS> = encode_MarkedTokenStream;
    const dec_ts: Decode<TS, HS> = decode_MarkedTokenStream;
    const dec_ts_ref: Decode<TS, HS> = decode_ref_MarkedTokenStream;
    const enc_span: Encode<Span, HS> = encode_MarkedSpan;
    const dec_span: Decode<Span, HS> = decode_MarkedSpan;
    const enc_sym: Encode<Symbol, HS> = encode_MarkedSymbol;
    const dec_sym: Decode<Symbol, HS> = decode_MarkedSymbol;
    const enc_tt: Encode<TokenTree<TS, Span, Symbol>, HS> = (t, w, s) => encode_TokenTree(t, w, s, enc_ts, enc_span, enc_sym);
    const dec_tt: Decode<TokenTree<TS, Span, Symbol>, HS> = (r, s) => decode_TokenTree(r, s, dec_ts, dec_span, dec_sym);
    const enc_opt_span: Encode<Span | undefined, HS> = (x, w, s) => encode_Option(x, w, s, enc_span);
    const enc_opt_string: Encode<string | undefined, HS> = (x, w, s) => encode_Option(x, w, s, encode_String);

    const reader: MutRef<Uint8Array> = { value: buf.deref() };

    /**
     * One arm's tail: run `call_method` (under `catch_unwind` unless already panicking), then
     * `buf.clear(); r.encode(&mut buf, handle_store);`.
     */
    const respond = <R>(call_method: () => R, encode_R: Encode<R, HS>): void => {
      // HACK(eddyb) don't use `panic::catch_unwind` in a panic.
      // If client and server happen to use the same `std`,
      // `catch_unwind` asserts that the panic counter was 0,
      // even when the closure passed to it didn't panic.
      let r: Result<R, PanicMessage>;
      if (panicking()) {
        r = { $: "Ok", _0: call_method() };
      } else {
        const c = catch_unwind(call_method);
        r = c.$ === "Ok" ? c : { $: "Err", _0: PanicMessage.from(c._0) };
      }

      buf.clear();
      encode_Result(r, buf, handle_store, encode_R, encode_PanicMessage);
    };

    switch (decode_ApiTags(reader, undefined)) {
      case "track_env_var":
        respond(() => {
          const var_ = unmark(decode_str(reader, handle_store));
          const value = unmark(decode_Option(reader, handle_store, decode_str));
          return server.track_env_var(var_, value);
        }, encode_unit);
        break;
      case "track_path":
        respond(() => {
          const path = unmark(decode_str(reader, handle_store));
          return server.track_path(path);
        }, encode_unit);
        break;
      case "literal_from_str":
        respond(
          () => {
            const s = unmark(decode_str(reader, handle_store));
            const r = server.literal_from_str(s);
            return mark(r);
          },
          (x, w, s) => encode_Result(x, w, s, (l: Literal<Span, Symbol>, w2: Buffer, s2: HS) => encode_Literal(l, w2, s2, enc_span, enc_sym), encode_String),
        );
        break;
      case "emit_diagnostic":
        respond(() => {
          const diagnostic = unmark(decode_Diagnostic(reader, handle_store, dec_span));
          return server.emit_diagnostic(diagnostic);
        }, encode_unit);
        break;
      case "ts_drop":
        respond(() => {
          const stream = unmark(dec_ts(reader, handle_store));
          return server.ts_drop(stream);
        }, encode_unit);
        break;
      case "ts_clone":
        respond(() => {
          const stream = unmark(dec_ts_ref(reader, handle_store));
          const r = server.ts_clone(stream);
          return mark(r);
        }, enc_ts);
        break;
      case "ts_is_empty":
        respond(() => {
          const stream = unmark(dec_ts_ref(reader, handle_store));
          const r = server.ts_is_empty(stream);
          return mark(r);
        }, encode_bool);
        break;
      case "ts_expand_expr":
        respond(
          () => {
            const stream = unmark(dec_ts_ref(reader, handle_store));
            const r = server.ts_expand_expr(stream);
            return mark(r);
          },
          (x, w, s) => encode_Result(x, w, s, enc_ts, encode_unit),
        );
        break;
      case "ts_from_str":
        respond(
          () => {
            const src = unmark(decode_str(reader, handle_store));
            const r = server.ts_from_str(src);
            return mark(r);
          },
          (x, w, s) => encode_Result(x, w, s, enc_ts, encode_String),
        );
        break;
      case "ts_to_string":
        respond(() => {
          const stream = unmark(dec_ts_ref(reader, handle_store));
          const r = server.ts_to_string(stream);
          return mark(r);
        }, encode_String);
        break;
      case "ts_from_token_tree":
        respond(() => {
          const tree = unmark(dec_tt(reader, handle_store));
          const r = server.ts_from_token_tree(tree);
          return mark(r);
        }, enc_ts);
        break;
      case "ts_concat_trees":
        respond(() => {
          const base = unmark(decode_Option(reader, handle_store, dec_ts));
          const trees = unmark(decode_Vec(reader, handle_store, dec_tt));
          const r = server.ts_concat_trees(base, trees);
          return mark(r);
        }, enc_ts);
        break;
      case "ts_concat_streams":
        respond(() => {
          const base = unmark(decode_Option(reader, handle_store, dec_ts));
          const streams = unmark(decode_Vec(reader, handle_store, dec_ts));
          const r = server.ts_concat_streams(base, streams);
          return mark(r);
        }, enc_ts);
        break;
      case "ts_into_trees":
        respond(
          () => {
            const stream = unmark(dec_ts(reader, handle_store));
            const r = server.ts_into_trees(stream);
            return mark(r);
          },
          (x, w, s) => encode_Vec(x, w, s, enc_tt),
        );
        break;
      case "span_debug":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_debug(span);
          return mark(r);
        }, encode_String);
        break;
      case "span_parent":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_parent(span);
          return mark(r);
        }, enc_opt_span);
        break;
      case "span_source":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_source(span);
          return mark(r);
        }, enc_span);
        break;
      case "span_byte_range":
        respond(
          () => {
            const span = unmark(dec_span(reader, handle_store));
            const r = server.span_byte_range(span);
            return mark(r);
          },
          (x, w, s) => encode_Range(x, w, s, encode_usize),
        );
        break;
      case "span_start":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_start(span);
          return mark(r);
        }, enc_span);
        break;
      case "span_end":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_end(span);
          return mark(r);
        }, enc_span);
        break;
      case "span_line":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_line(span);
          return mark(r);
        }, encode_usize);
        break;
      case "span_column":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_column(span);
          return mark(r);
        }, encode_usize);
        break;
      case "span_file":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_file(span);
          return mark(r);
        }, encode_String);
        break;
      case "span_local_file":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_local_file(span);
          return mark(r);
        }, enc_opt_string);
        break;
      case "span_join":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const other = unmark(dec_span(reader, handle_store));
          const r = server.span_join(span, other);
          return mark(r);
        }, enc_opt_span);
        break;
      case "span_subspan":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const start = unmark(decode_Bound(reader, handle_store, decode_usize));
          const end = unmark(decode_Bound(reader, handle_store, decode_usize));
          const r = server.span_subspan(span, start, end);
          return mark(r);
        }, enc_opt_span);
        break;
      case "span_resolved_at":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const at = unmark(dec_span(reader, handle_store));
          const r = server.span_resolved_at(span, at);
          return mark(r);
        }, enc_span);
        break;
      case "span_source_text":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_source_text(span);
          return mark(r);
        }, enc_opt_string);
        break;
      case "span_save_span":
        respond(() => {
          const span = unmark(dec_span(reader, handle_store));
          const r = server.span_save_span(span);
          return mark(r);
        }, encode_usize);
        break;
      case "span_recover_proc_macro_span":
        respond(() => {
          const id = unmark(decode_usize(reader, handle_store));
          const r = server.span_recover_proc_macro_span(id);
          return mark(r);
        }, enc_span);
        break;
      case "symbol_normalize_and_validate_ident":
        respond(
          () => {
            const string = unmark(decode_str(reader, handle_store));
            const r = server.symbol_normalize_and_validate_ident(string);
            return mark(r);
          },
          (x, w, s) => encode_Result(x, w, s, enc_sym, encode_unit),
        );
        break;
    }
    return buf;
  }
}

// This trait is currently only implemented and used once, inside of this crate.
// We keep it public to allow implementing more complex execution strategies in
// the future, such as wasm proc-macros.
// std-type: library/proc_macro/src/bridge/server.rs:137 ExecutionStrategy
export interface ExecutionStrategy {
  // std: library/proc_macro/src/bridge/server.rs:138 run_bridge_and_client
  run_bridge_and_client<TokenStream, Span, Symbol>(
    dispatcher: Dispatcher<TokenStream, Span, Symbol>,
    input: Buffer,
    run_client: (config: BridgeConfig) => Buffer,
    force_show_panics: boolean,
  ): Buffer;
}

// thread_local! {
/// While running a proc-macro with the same-thread executor, this flag will
/// be set, forcing nested proc-macro invocations (e.g. due to
/// `TokenStream::expand_expr`) to be run using a cross-thread executor.
///
/// This is required as the thread-local state in the proc_macro client does
/// not handle being re-entered, and will invalidate all `Symbol`s when
/// entering a nested macro.
let ALREADY_RUNNING_SAME_THREAD = false;
// }

/// Keep `ALREADY_RUNNING_SAME_THREAD` (see also its documentation)
/// set to `true`, preventing same-thread reentrance.
// std-type: library/proc_macro/src/bridge/server.rs:160 RunningSameThreadGuard
class RunningSameThreadGuard {
  // std: library/proc_macro/src/bridge/server.rs:163 new
  static new(): RunningSameThreadGuard {
    // `ALREADY_RUNNING_SAME_THREAD.replace(true)`
    const already_running = ALREADY_RUNNING_SAME_THREAD;
    ALREADY_RUNNING_SAME_THREAD = true;
    assert(!already_running, 'same-thread nesting ("reentrance") of proc macro executions is not supported');
    return new RunningSameThreadGuard();
  }

  // impl Drop for RunningSameThreadGuard
  // std: library/proc_macro/src/bridge/server.rs:174 drop
  drop(): void {
    ALREADY_RUNNING_SAME_THREAD = false;
  }
}

// std-type: library/proc_macro/src/bridge/server.rs:179 MaybeCrossThread
export class MaybeCrossThread implements ExecutionStrategy {
  constructor(public cross_thread: boolean) {}

  // impl ExecutionStrategy for MaybeCrossThread
  // std: library/proc_macro/src/bridge/server.rs:187 run_bridge_and_client
  run_bridge_and_client<TokenStream, Span, Symbol>(
    dispatcher: Dispatcher<TokenStream, Span, Symbol>,
    input: Buffer,
    run_client: (config: BridgeConfig) => Buffer,
    force_show_panics: boolean,
  ): Buffer {
    if (this.cross_thread || ALREADY_RUNNING_SAME_THREAD) {
      // let (mut server, mut client) = MessagePipe::new();
      // let join_handle = thread::spawn(move || { .. run_client(BridgeConfig { input, dispatch, force_show_panics }) });
      // while let Some(b) = server.recv() { server.send(dispatcher.dispatch(b)); }
      // join_handle.join().unwrap()
      return unported(
        "proc_macro::bridge::server::MaybeCrossThread::run_bridge_and_client (cross-thread proc-macro execution: -Zproc-macro-execution-strategy=cross-thread or a nested proc macro)",
      );
    } else {
      const _guard = RunningSameThreadGuard.new();
      try {
        const dispatch = (buf: Buffer): Buffer => dispatcher.dispatch(buf);

        return run_client({ input, dispatch: Closure.from(dispatch), force_show_panics });
      } finally {
        _guard.drop();
      }
    }
  }
}

export const SAME_THREAD: MaybeCrossThread = new MaybeCrossThread(false);
export const CROSS_THREAD: MaybeCrossThread = new MaybeCrossThread(true);

/// A message pipe used for communicating between server and client threads.
