/** `<Option<MarkedTokenStream<S>>>::unmark(s).unwrap_or_default()` */
function unwrap_or_default_TokenStream<TokenStream, Span, Symbol>(
  server: Server<TokenStream, Span, Symbol>,
  s: TokenStream | undefined,
): TokenStream {
  if (s !== undefined) return s;
  const default_TokenStream = statics_of(server).default_TokenStream;
  if (default_TokenStream === undefined) {
    return unported("proc_macro::bridge::server::Client::run (the server class has no static default_TokenStream)");
  }
  return default_TokenStream();
}

